export function inspectPokemonGroups(groups: PokemonGroup[]) {
  const members = groups.flatMap((group) => group.members);
  const uniqueKeys = new Set(members.map((member) => `${member.id}-${member.subId ?? 0}`));
  const specialFormKeys = new Set(
    members
      .filter((member) => (member.subId ?? 0) > 0)
      .map((member) => `${member.id}-${member.subId}`),
  );

  return {
    groupCount: groups.length,
    memberCount: members.length,
    uniqueMemberCount: uniqueKeys.size,
    repeatedPlacementCount: members.length - uniqueKeys.size,
    specialFormCount: specialFormKeys.size,
    invalidGroupCount: groups.filter((group) => group.members.length !== 5).length,
    invalidStageCount: members.filter((member) => (member.subId ?? 0) === 0 && member.stage < 2).length,
  };
}
